from typing import List, Tuple, Set

def tuple_intersection(list1: List[Tuple], list2: List[Tuple]) -> Set[Tuple]:
    """
    Returns the intersection of two lists of tuples, ignoring the order of elements within each tuple.
    """
    set1 = {tuple(sorted(t)) for t in list1}
    set2 = {tuple(sorted(t)) for t in list2}
    return set1.intersection(set2)
